class Emitter {
  constructor() { this.h = {}; }
  on(e, f) { (this.h[e] ??= []).push(f); return this; }
  off(e, f) { this.h[e] = (this.h[e] || []).filter((x) => x !== f && x.orig !== f); return this; }
  once(e, f) {
    const w = (...a) => { this.off(e, w); f(...a); };
    w.orig = f;
    return this.on(e, w);
  }
  emit(e, ...a) {
    [...(this.h[e] || [])].forEach((f) => f(...a));
    return (this.h[e] || []).length;
  }
}
const em = new Emitter();
em.once('x', (v) => console.log('once', v));
em.on('x', (v) => console.log('on', v));
console.log(em.emit('x', 1));
console.log(em.emit('x', 2));

