function all(promises) {
  return new Promise((resolve, reject) => {
    const results = [];
    promises.forEach((p) =>
      Promise.resolve(p).then((v) => {
        results.push(v);
        if (results.length === promises.length) resolve(results);
      }, reject)
    );
  });
}

